var SYN={};[['outcome',['goal','objective','aim']],['error',['mistake','bug','fail','failure']]].forEach(function(p){var t=stem0(p[0]);p[1].forEach(function(w){SYN[stem0(w)]=t;});});
function stem(w){w=stem0(w);return SYN[w]||w;}
function tokens(s){return s.toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(function(w){return w.length>1&&!STOP.has(w);}).map(stem);}

